(6019627, 880955, 117153, '<td valign="top">Lots of noise, shot has been overworked and therefore creates a loss in detail, good angle makes it interesting though. Composition good.</td>', 'Lots of noise, shot has been overworked and therefore creates a loss in detail, good angle makes it interesting though. Composition good.', '2010-05-21 06:40:56.000000', NULL, 1),
(6019628, 882330, 117153, '<td valign="top">Wow excellent, love the use of depth of field. watch that you dont crop your subject matter too tightly, esp at the bottom, would have been nice with a little more room there. Great colours, well done.</td>', 'Wow excellent, love the use of depth of field. watch that you dont crop your subject matter too tightly, esp at the bottom, would have been nice with a little more room there. Great colours, well done.', '2010-05-21 06:42:41.000000', NULL, 1),
(6019629, 880815, 117153, '<td valign="top">My eye is drawn to the key hole which is the darkest tone in the photo, which is not in focus. makes the eye compete with the "Abus" wording that is in focus, Nice angle.</td>', 'My eye is drawn to the key hole which is the darkest tone in the photo, which is not in focus. makes the eye compete with the "Abus" wording that is in focus, Nice angle.', '2010-05-21 06:44:39.000000', NULL, 1),
(6019630, 882467, 117153, '<td valign="top">Nice subject matter, well shot.</td>', 'Nice subject matter, well shot.', '2010-05-21 06:45:17.000000', NULL, 1),
(6019631, 881254, 117153, '<td valign="top">Beautiful shot, love the use of the red reflection, makes the silver handle really stand out. well done. Good composition.</td>', 'Beautiful shot, love the use of the red reflection, makes the silver handle really stand out. well done. Good composition.', '2010-05-21 06:46:15.000000', NULL, 1),
(6019632, 881725, 117153, '<td valign="top">Lovely composition, perfect on the eye. Nice angle.</td>', 'Lovely composition, perfect on the eye. Nice angle.', '2010-05-21 06:46:49.000000', NULL, 1),
(6019633, 883294, 117153, '<td valign="top">Good shot, nice angle.</td>', 'Good shot, nice angle.', '2010-05-21 06:47:18.000000', NULL, 1),
(6019634, 882593, 117153, '<td valign="top">Good use of depth of field, although the out of focus latch to the right of the lock is too distracting. Warmer light would have helped.</td>', 'Good use of depth of field, although the out of focus latch to the right of the lock is too distracting. Warmer light would have helped.', '2010-05-21 06:48:34.000000', NULL, 1),
(6019635, 881803, 117153, '<td valign="top">Good composition, interesting suject matter, would have liked more contrast to bring out the wood tones, but very nice.</td>', 'Good composition, interesting suject matter, would have liked more contrast to bring out the wood tones, but very nice.', '2010-05-21 06:49:35.000000', NULL, 1),
(6019636, 882968, 117153, '<td valign="top">The door panel slices the photo in half, so the outside scene competes with your door, I would have shot either more door, or more of the outside scene, nice shot though, creates two different atmospheres.</td>', 'The door panel slices the photo in half, so the outside scene competes with your door, I would have shot either more door, or more of the outside scene, nice shot though, creates two different atmospheres.', '2010-05-21 06:51:16.000000', NULL, 1),
(6019637, 882322, 117153, '<td valign="top">Nice interesting shot, good use of angles. Your background is also interesting which is unusual when its a dark background, but well done.</td>', 'Nice interesting shot, good use of angles. Your background is also interesting which is unusual when its a dark background, but well done.', '2010-05-21 06:53:52.000000', NULL, 1),
