(6019651, 882631, 117153, '<td valign="top">Over sharpened and lose of detail, but nice composition.</td>', 'Over sharpened and lose of detail, but nice composition.', '2010-05-21 07:18:41.000000', NULL, 1),
(6019653, 883093, 117153, '<td valign="top">Angle to much feels like the photo is falling over to the right, door knob needs to be in focus, and not in the middle of the photo.</td>', 'Angle to much feels like the photo is falling over to the right, door knob needs to be in focus, and not in the middle of the photo.', '2010-05-21 07:19:42.000000', NULL, 1),
