(6019666, 882370, 117153, '<td valign="top">Excellent, lovely shot. Nice angle good capture of colour, and depth of field</td>', 'Excellent, lovely shot. Nice angle good capture of colour, and depth of field', '2010-05-21 07:27:53.000000', NULL, 1),
