(6019680, 883059, 117153, '<td valign="top">Be careful how the shot is cropped, cutting off the keys at the bottom and the detail at the top isnt pleasing on the eye, making use of the portrait shot would have been better than the landscape, next time watch your composition. Good clarity though and nice lighting.</td>', 'Be careful how the shot is cropped, cutting off the keys at the bottom and the detail at the top isnt pleasing on the eye, making use of the portrait shot would have been better than the landscape, next time watch your composition. Good clarity though and nice lighting.', '2010-05-21 07:40:39.000000', NULL, 1),
(6019682, 880722, 117153, '<td valign="top">Not a very interesting shot, but nice use of lighting, nice focus.</td>', 'Not a very interesting shot, but nice use of lighting, nice focus.', '2010-05-21 07:41:27.000000', NULL, 1),
